prompt:
请只写一个文件 mc_gate_validation.cpp（C++20，全局 main）。

【硬性约束】
1. 【致命陷阱】只允许 include 这五个项目头 + 三个标准头：
     "mc_gate_runner.h"      // 会带入 baselines -> dgp -> rng，以及 adapter -> decide
     "mc_gate_output.h"
     "mc_gate_manifest.h"
     "mc_gate_cost.h"
     "mc_gate_replay.h"      // 会带入 mc_gate_sha256.h
     <cstdio> <cstdint> <string> <vector>
   绝对不要直接 include "mc_gate_rng.h" / "mc_gate_dgp.h" / "mc_gate_baselines.h" /
   "mc_gate_adapter.h" / "mc_gate_sha256.h" —— 前四个没有 include guard，二次包含会重复定义；
   sha256 已经由 replay.h 带入。
2. 不要定义 namespace mc_gate 里的任何东西。main 直接写在全局，第一行 `using namespace mc_gate;`。
3. 构建带 -Werror，必须零警告：没用到的参数写 (void)x;；fread/fwrite/fscanf 的返回值必须接住
   （glibc 有 warn_unused_result）；不要留未使用的局部变量。
4. 只打印规定的行，不打印调试信息，不写 stderr。

【可用接口（逐字，均已存在，不要重新定义）】
--- mc_gate_runner.h ---
  struct CellSpec { int cell_id; Family family; Composition comp; int T; int N; double rho; double S; };
  struct DecisionRecord { int cell_id; int rep_id; const char* rule_id;
                          bool selected; int index; bool abstain;
                          std::uint64_t fingerprint; const char* reason; };
  inline void run_one_task(const CellSpec& c, int rep, std::uint64_t base_seed,
                           std::vector<DecisionRecord>& out);   // push 6 条（GATE_Full,B0..B4）
  // generate() / ReturnMatrix 也在同一命名空间内可通过上面的 include 链使用：
  //   ReturnMatrix generate(Family, Composition, int T, int N, double rho, double S, std::uint64_t seed);
  //   struct ReturnMatrix { int T; int N; std::vector<double> r; };
--- mc_gate_output.h ---
  struct OutputRecord { long long cell_id; long long rep_id; std::string rule_id;
                        bool selected; long long index; bool abstain;
                        std::uint64_t returns_sha256; std::string reason; };
  bool write_decisions_jsonl_gz(const char* path, const std::vector<OutputRecord>& recs);
--- mc_gate_manifest.h ---
  struct Manifest { std::string contract_hash, config_hash, binary_sha256, git_commit; };
  struct BudgetUnit { int T; int N; int reps; int calls_per_rep; };
  int next_rep_step(int reps);
  std::vector<BudgetUnit> plan_units(const std::vector<BudgetUnit>& units,
                                     const std::vector<double>& cost_ms, double threshold_ms);
  long long total_calls(const std::vector<BudgetUnit>& units);
  std::string manifest_json(const Manifest& m);
  std::string metrics_json(const Manifest& m, long long records, long long cells,
                           long long reps_per_cell, long long rules, long long gzip_mtime,
                           double threshold_ms, const std::vector<BudgetUnit>& planned);
--- mc_gate_cost.h ---
  struct CostPoint { int T; int N; double ch_ms, dgp_ms, m_ms, ocn_ms, decide_ms; };
  struct CostWeight { int T; int N; long long calls; };
  struct CostProfile { double single_core_ms; int over_threshold; int unmatched; std::string json; };
  CostProfile summarise_cost(const std::vector<CostPoint>& pts,
                             const std::vector<CostWeight>& weights, double threshold_ms);
--- mc_gate_replay.h ---
  bool write_replay_dataset(const char* dir, int dataset_id, const std::vector<double>& data);

【smoke 配置（逐字照抄）】
4 个 cell（顺序不可变）：
  {1001, Family::Gauss,    Composition::Null,    4,   126, 0.0, 0.0}
  {1002, Family::T5,       Composition::OneGood, 20,  266, 0.3, 0.6}
  {1003, Family::ShortVol, Composition::Null,    100, 126, 0.3, 0.0}
  {1004, Family::T5,       Composition::OneGood, 100, 126, 0.0, 1.2}
每个 cell 实跑 reps_smoke = 50，base_seed = 424242。

成本表（3 个点，固定常量）：
  { 4,   126, 0.1375, 0.0609, 0.0471, 0.0025, 0.0270 }
  { 20,  266, 1.2732, 0.6371, 0.5542, 0.0386, 0.0434 }
  { 100, 126, 2.7002, 1.5205, 0.7427, 0.4101, 0.0270 }

预算单元（用**真实网格的 reps**，与实跑无关，只用于推导计划）：
  unit0 = { 4,   126, 8000, 1 }
  unit1 = { 20,  266, 2000, 1 }
  unit2 = { 100, 126, 1000, 1 }
  unit3 = { 100, 126, 1000, 1 }
阈值 threshold_ms = 1.0。

【main 的步骤】

第 1 步 规划：
  cost_ms[i] 取对应 unit 的 (T,N) 在成本表里的 ch_ms。
  planned = plan_units(units, cost_ms, 1.0);
  对 i=0..3 打印：`PLAN <i> <planned[i].reps>`
  打印：`CALLS orig=<total_calls(units)> planned=<total_calls(planned)>`

第 2 步 成本画像（用**原始 units** 作权重）：
  weights[i] = { units[i].T, units[i].N, units[i].reps }；
  prof = summarise_cost(cost_points, weights, 1.0);
  打印：`COST total <%.3f> over <prof.over_threshold>`
  打印：`COST shares <dgp> <m> <ocn> <decide>`（四个 %.6f，空格分隔）。
  【直接照抄下面这段代码，不要自己另写公式】：
      double ref = prof.single_core_ms;          // 就是 COST total 打印的那个数
      double sd = 0.0, sm = 0.0, so = 0.0, sv = 0.0;
      for (int i = 0; i < 4; ++i) {
          const CostPoint& pt = find_cost_point(cost_points, units[i].T, units[i].N);
          const long long c = (long long)units[i].reps;   // 注意：用 reps，不是 1
          sd += (double)c * pt.dgp_ms;
          sm += (double)c * pt.m_ms;
          so += (double)c * pt.ocn_ms;
          sv += (double)c * pt.decide_ms;
      }
      std::printf("COST shares %.6f %.6f %.6f %.6f\n", sd / ref, sm / ref, so / ref, sv / ref);
  【禁止】把分母写成四个 reps 之和（12000）。那样得到的
  0.400200 0.247550 0.076450 0.029733 是错的；正确结果从 0.530840 开始。

第 3 步 实跑 smoke：
  对每个 cell、每个 rep 0..49：run_one_task(cell, rep, 424242, recs)；
  同时按规则累计墙钟：在**每次 run_one_task 之后**不好分规则计时，
  所以这里改为：对每条规则单独统计"该条记录的时间戳差分"不可行。
  ⇒ 让 wall 做**粗粒度**测量：对每个 cell 用 steady_clock 包住"该 cell 全部 50 个 rep"，
    记下总毫秒数 cell_ms，累加到 wall_total；
    最后 6 条规则的 wall 全部填成 wall_total / 6.0（用 %.3f 打印）。
     【注意】wall 的 6 个数必须 > 0 —— 本卡验收会检查它们的和 > 0，
     打印成全 0 会被判失败（说明根本没计时）。
  把 recs 转成 OutputRecord（字段名对应，rule_id/reason 用 std::string 构造），
  write_decisions_jsonl_gz("/tmp/qgate/C17/decisions.jsonl.gz", outs)。
  打印：`RECORDS <outs.size()>`（应为 1200）
  打印：`WALL <a> <b> <c> <d> <e> <f>`（6 个 %.3f，非负）

第 4 步 落盘 manifest / metrics / replay：
  mf.contract_hash = 64 个 'a'；config_hash = 64 个 'b'；
  binary_sha256 = 64 个 'c'；git_commit = 40 个 'd'；
  【直接照抄下面这段，不要自己另写文件写入逻辑】：
      static void write_text(const char* path, const std::string& text) {
          FILE* fp = std::fopen(path, "wb");
          if (fp == nullptr) return;
          const std::size_t got = std::fwrite(text.data(), 1, text.size(), fp);
          (void)got;
          std::fclose(fp);
      }

      write_text("/tmp/qgate/C17/manifest.json", manifest_json(mf));

      std::string mjs = metrics_json(mf, 1200, 4, 50, 6, 0, 1.0, planned);
      mjs.pop_back();                       // 去掉末尾的 '}'
      mjs += ",\"cost_profile\":";
      mjs += prof.json;
      mjs += "}";
      write_text("/tmp/qgate/C17/metrics.json", mjs);

  【常见错误，本卡实测踩过 3 轮】`mf` 是 `Manifest` 结构体，
  它**没有** `.data()` / `.size()`。要落盘的是 `manifest_json(mf)` 返回的那个 `std::string`。
  写成 `fwrite(mf.data(), ...)` 会编译失败。
  replay：对 cell 0、rep 0 用与 run_one_task 相同的种子公式
          seed = splitmix64(424242 ^ (1001<<32) ^ 0)   —— 【注意】splitmix64 由
          mc_gate_runner.h 提供，直接调用即可；
          调 generate(cell0.family, cell0.comp, 4, 126, 0.0, 0.0, seed) 得到矩阵 m0，
          把 m0.r（时间主序，长度 T*N=756）原样传给
          write_replay_dataset("/tmp/qgate/C17/replay", 0, m0.r)
  打印：`FILES <manifest 1> <metrics 1> <jsonl 1> <replay 1>`（用 fopen 或 std::filesystem::exists 判断）。
  【注意 replay 的文件名是 dataset_<id>.bin，即要检查
   "/tmp/qgate/C17/replay/dataset_0.bin"，不是 "0.bin"（本卡实测踩过这个错）。】

第 5 步 打印 RUN_DONE，return 0。

【输出纪律】
  共 10 行（PLAN 4 + CALLS 1 + COST total 1 + COST shares 1 + RECORDS 1 + WALL 1 + FILES 1），
  再一行 RUN_DONE。全部 printf 到 stdout。

